func TestGeneratedInboundRuntimeBoundary(t *testing.T) {
	files, err := planFiles(generator.GoOptions{ImportPath: "example.test/consumer/api", Package: "api"}, nil, false, false, "server-handler", "server-parameters")
	if err != nil {
		t.Fatal(err)
	}
	root := testGeneratedModule(t, generator.NewPlan("golang", sourcePlan{Files: files}), map[string]string{"api/server/runtime/inbound_test.go": inboundRuntimeConsumer, "api/server/runtime/coercion_test.go": inboundCoercionConsumer})
	checkInboundImportGraph(t, root, "runtime", false)
}

func checkInboundImportGraph(t *testing.T, root, pkg string, modelsAllowed bool) {
	t.Helper()
	ctx, cancel := context.WithTimeout(context.Background(), time.Minute)
	defer cancel()
	command := exec.CommandContext(ctx, "go", "list", "-mod=readonly", "-deps", "example.test/consumer/api/server/"+pkg)
	command.WaitDelay = 5 * time.Second
	command.Dir = root
	command.Env = append(os.Environ(), "GOWORK=off", "GOTOOLCHAIN=local")
	output, err := command.CombinedOutput()
	if err != nil {
		t.Fatalf("server runtime graph: %v\n%s", err, output)
	}
	for _, dependency := range strings.Fields(string(output)) {
		if dependency == "example.test/consumer/api" || !modelsAllowed && dependency == "example.test/consumer/api/models" || strings.HasPrefix(dependency, "example.test/consumer/api/internal/core") || strings.HasPrefix(dependency, "example.test/consumer/api/internal/transport") || strings.HasPrefix(dependency, "example.test/consumer/api/internal/operations") || strings.HasPrefix(dependency, "example.test/consumer/api/selective") {
			t.Fatal("server runtime imports a client layer", dependency)
		}
	}
}

const inboundRuntimeConsumer = `package runtime
import("bytes";"context";"errors";"fmt";"io";"net/http";"net/http/httptest";"strings";"sync";"sync/atomic";"testing";"time";"example.test/consumer/api/types")
type countedBody struct{io.Reader;closes atomic.Int32}
func(body *countedBody)Close()error{body.closes.Add(1);return nil}
type rejectionSource struct{opens,closes atomic.Int32}
func(source *rejectionSource)Metadata()types.BinaryMetadata{return types.BinaryMetadata{ContentType:"text/plain"}}
func(source *rejectionSource)Open(context.Context)(io.ReadCloser,error){source.opens.Add(1);return &rejectionReader{Reader:strings.NewReader("denied"),source:source},nil}
type rejectionReader struct{io.Reader;source *rejectionSource}
func(reader *rejectionReader)Close()error{reader.source.closes.Add(1);return nil}
func requiredDefinition()Definition{security,_:=types.ValueFrom([]any{map[string]any{"Key":[]any{}}});return Definition{OperationID:"event",Method:"POST",Security:security,Schemes:[]InboundScheme{ {Identity:"Key",Definition:types.SecuritySchemeDefinition{Name:"Key",Type:"apiKey",Location:"header",ParameterName:"X-Key"}},{Identity:"Query",Definition:types.SecuritySchemeDefinition{Name:"Query",Type:"apiKey",Location:"query",ParameterName:"q"}} },DecodeParameters:func(execution *Execution,path map[string]string)(ParameterResult,error){value,err:=types.ValueFrom(map[string]any{"path":path});return ParameterResult{Value:value},err}}}
func TestAuthenticationSnapshotAndBodyClone(t *testing.T){definition:=requiredDefinition();var calls atomic.Int32;handler,err:=NewHandler("/hooks/이벤트/{tenant}",definition,Options{Authenticate:func(ctx context.Context,info InboundRequestContext)(*InboundRejection,error){if info.Request.Body!=http.NoBody||info.OperationID!="event"||info.Method!="POST"||len(info.SecurityCandidates)!=2||info.SecurityCandidates[0].Value!="token"||info.SecurityCandidates[1].Value!="one;two"{t.Error(info)};path,_:=info.Params.Get("path");tenant,_:=path.Get("tenant");if text,_:=tenant.String();text!="a/b"{t.Error(text)};info.Request.Header.Set("X-Key","changed");var wait sync.WaitGroup;for range 8{wait.Go(func(){body,err:=info.CloneBody(ctx);if err!=nil{t.Error(err);return};defer body.Close();value,err:=io.ReadAll(body);if err!=nil||string(value)!="payload"{t.Error(string(value),err)}})};wait.Wait();return nil,nil}},func(execution *Execution,_ ParameterResult)(Response,error){calls.Add(1);if execution.Request.Header.Get("X-Key")!="token"{t.Error("metadata mutation reached request")};request,err:=execution.BodyRequest();if err!=nil{return Response{},err};body,err:=io.ReadAll(request.Body);request.Body.Close();if err!=nil||string(body)!="payload"{t.Error(string(body),err)};return Response{Status:200,HasBody:true,Body:types.BinaryFromString("ok")},nil});if err!=nil{t.Fatal(err)};server:=httptest.NewServer(handler);defer server.Close();request,_:=http.NewRequest("POST",server.URL+"/hooks/%ec%9d%b4%eb%b2%a4%ed%8a%b8/a%2fb?q=one;two",strings.NewReader("payload"));request.Header.Set("X-Key","token");response,err:=server.Client().Do(request);if err!=nil{t.Fatal(err)};defer response.Body.Close();body,_:=io.ReadAll(response.Body);if response.StatusCode!=200||string(body)!="ok"||calls.Load()!=1{t.Fatal(response.StatusCode,string(body),calls.Load())}}
func TestInboundAuthenticationAndLimitFailures(t *testing.T){for _,test:=range []struct{name string;options Options;anonymous bool;status int}{
 {name:"missing",status:401},
 {name:"auth-error",options:Options{Authenticate:func(context.Context,InboundRequestContext)(*InboundRejection,error){return nil,errors.New("private credential data")}},status:500},
 {name:"clone-limit",options:Options{MaxBodyBytes:3,Authenticate:func(ctx context.Context,info InboundRequestContext)(*InboundRejection,error){_,err:=info.CloneBody(ctx);return nil,err}},status:413},
 {name:"anonymous",anonymous:true,options:Options{Authenticate:func(context.Context,InboundRequestContext)(*InboundRejection,error){t.Error("anonymous auth invoked");return nil,nil}},status:204},
 }{t.Run(test.name,func(t *testing.T){definition:=requiredDefinition();if test.anonymous{definition.Security,_=types.ValueFrom([]any{map[string]any{}})};called:=false;handler,err:=NewHandler("/",definition,test.options,func(*Execution,ParameterResult)(Response,error){called=true;return Response{Status:204},nil});if err!=nil{t.Fatal(err)};body:=&countedBody{Reader:strings.NewReader("payload")};request:=httptest.NewRequest("POST","http://example.test/",body);request.ContentLength=1;writer:=httptest.NewRecorder();handler.ServeHTTP(writer,request);if writer.Code!=test.status||body.closes.Load()!=1||called!=test.anonymous||strings.Contains(writer.Body.String(),"private"){t.Fatal(writer.Code,body.closes.Load(),called,writer.Body.String())}})}}
func TestRejectionAndDuplexCapability(t *testing.T){source:=new(rejectionSource);handler,err:=NewHandler("/",requiredDefinition(),Options{Authenticate:func(context.Context,InboundRequestContext)(*InboundRejection,error){return &InboundRejection{Status:403,Headers:http.Header{"X-Rejected":{"yes"}},Body:source},nil}},func(*Execution,ParameterResult)(Response,error){t.Error("rejected handler ran");return Response{},nil});if err!=nil{t.Fatal(err)};writer:=httptest.NewRecorder();handler.ServeHTTP(writer,httptest.NewRequest("POST","http://example.test/",nil));if writer.Code!=403||writer.Body.String()!="denied"||writer.Header().Get("X-Rejected")!="yes"||source.opens.Load()!=1||source.closes.Load()!=1{t.Fatal(writer.Code,writer.Body.String(),source.opens.Load(),source.closes.Load())}
 source=new(rejectionSource);var reported error;definition:=requiredDefinition();definition.Security=types.Value{};definition.Streaming=func(string)bool{return true};handler,err=NewHandler("/",definition,Options{OnError:func(_ context.Context,err error){reported=err}},func(*Execution,ParameterResult)(Response,error){return Response{Status:200,HasBody:true,Streaming:true,Body:types.BinaryFromSource(source)},nil});if err!=nil{t.Fatal(err)};writer=httptest.NewRecorder();handler.ServeHTTP(writer,httptest.NewRequest("POST","http://example.test/",strings.NewReader("unread")));var capability *types.SDKError;if writer.Code!=500||!errors.As(reported,&capability)||capability.Code!=types.TransportCapabilityRequired||source.opens.Load()!=0||source.closes.Load()!=0{t.Fatal(writer.Code,reported,source.closes.Load())}
}
func TestInboundQueryAndCookieLexemes(t *testing.T){values:=formValues("x=a%2Bb&x=c+d&semi=a;b&bad=%zz&utf=%ff");if len(values["x"])!=2||values["x"][0]!="a+b"||values["x"][1]!="c d"||values["semi"][0]!="a;b"||values["bad"][0]!="%zz"||!bytes.Equal([]byte(values["utf"][0]),[]byte{0xef,0xbf,0xbd}){t.Fatal(values)};raw,decoded:=cookieValues("x=a+b; x=a%20b; bad=%ff");if raw["x"][1]!="a%20b"||decoded["x"][0]!="a+b"||decoded["x"][1]!="a b"||decoded["bad"][0]!="%ff"{t.Fatal(raw,decoded)}}
type blockedBody struct{started,closed chan struct{};start,close sync.Once;closes atomic.Int32}
func(body *blockedBody)Read([]byte)(int,error){body.start.Do(func(){close(body.started)});<-body.closed;return 0,io.ErrClosedPipe}
func(body *blockedBody)Close()error{body.close.Do(func(){body.closes.Add(1);close(body.closed)});return nil}
func TestCancellationInterruptsBodyAndPreservesPhase(t *testing.T){var reported error;definition:=requiredDefinition();definition.Security=types.Value{};handler,err:=NewHandler("/",definition,Options{OnError:func(_ context.Context,err error){reported=err}},func(execution *Execution,_ ParameterResult)(Response,error){_,err:=execution.BodyRequest();return Response{},err});if err!=nil{t.Fatal(err)};body:=&blockedBody{started:make(chan struct{}),closed:make(chan struct{})};ctx,cancel:=context.WithCancel(context.Background());defer cancel();request:=httptest.NewRequest("POST","http://example.test/",body).WithContext(ctx);done:=make(chan struct{});go func(){defer close(done);handler.ServeHTTP(httptest.NewRecorder(),request)}();select{case <-body.started:case <-time.After(5*time.Second):t.Fatal("body read did not start")};cancel();select{case <-done:case <-time.After(5*time.Second):t.Fatal("canceled body read blocked")};var failure *Error;if body.closes.Load()!=1||!errors.As(reported,&failure)||failure.Code!=InboundRequestAborted||!errors.Is(reported,context.Canceled){t.Fatal(body.closes.Load(),reported)}}
func TestRealDuplexHeadersBeforeInput(t *testing.T){for _,test:=range []struct{name string;http2,streaming bool}{ {name:"http1-stream",streaming:true},{name:"http2-stream",http2:true,streaming:true},{name:"http1-finite"} }{t.Run(test.name,func(t *testing.T){definition:=Definition{OperationID:"duplex",Method:"POST",Streaming:func(string)bool{return true}};handler,err:=NewHandler("/",definition,Options{},func(execution *Execution,_ ParameterResult)(Response,error){if test.streaming{return Response{Status:200,HasBody:true,Streaming:true,Body:types.BinaryFromReader(execution.Request.Body,types.BinaryMetadata{ContentType:"application/octet-stream"})},nil};return Response{Status:200,HasBody:true,Body:types.BinaryFromString("ok")},nil});if err!=nil{t.Fatal(err)};done:=make(chan struct{});server:=httptest.NewUnstartedServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){defer close(done);handler.ServeHTTP(w,r)}));server.EnableHTTP2=test.http2;if test.http2{server.StartTLS()}else{server.Start()};defer server.Close();ctx,cancel:=context.WithTimeout(context.Background(),2*time.Second);defer cancel();reader,writer:=io.Pipe();defer reader.Close();defer writer.Close();stop:=context.AfterFunc(ctx,func(){reader.CloseWithError(ctx.Err())});defer stop();request,_:=http.NewRequestWithContext(ctx,"POST",server.URL,reader);request.Header.Set("Content-Type","application/x-ndjson");response,err:=server.Client().Do(request);if err!=nil{t.Fatal("response headers waited for request input",err)};defer response.Body.Close();if test.http2&&response.ProtoMajor!=2{t.Fatal("HTTP/2 not negotiated")};expected:="ok";if test.streaming{expected="payload";if _,err:=io.WriteString(writer,expected);err!=nil{t.Fatal(err)};writer.Close()};body,err:=io.ReadAll(response.Body);if err!=nil||string(body)!=expected{t.Fatal(string(body),err)};cancel();writer.Close();select{case <-done:case <-time.After(3*time.Second):t.Fatal("duplex cleanup blocked")}})}}
func TestRealEarlyErrorsBeforeInput(t *testing.T){for _,http2:=range []bool{false,true}{for _,status:=range []int{401,500}{name:=fmt.Sprintf("http2=%t/status=%d",http2,status);t.Run(name,func(t *testing.T){definition:=Definition{OperationID:"early",Method:"POST",Streaming:func(string)bool{return true}};if status==401{definition.Security,_=types.ValueFrom([]any{map[string]any{"Key":[]any{}}})};handler,err:=NewHandler("/",definition,Options{},func(*Execution,ParameterResult)(Response,error){return Response{},errors.New("private handler details")});if err!=nil{t.Fatal(err)};server:=httptest.NewUnstartedServer(handler);server.EnableHTTP2=http2;if http2{server.StartTLS()}else{server.Start()};defer server.Close();ctx,cancel:=context.WithTimeout(context.Background(),2*time.Second);defer cancel();reader,writer:=io.Pipe();defer reader.Close();defer writer.Close();stop:=context.AfterFunc(ctx,func(){reader.CloseWithError(ctx.Err())});defer stop();request,_:=http.NewRequestWithContext(ctx,"POST",server.URL,reader);request.Header.Set("Content-Type","application/x-ndjson");response,err:=server.Client().Do(request);if err!=nil{t.Fatal("error response waited for input",err)};defer response.Body.Close();body,err:=io.ReadAll(response.Body);if err!=nil||response.StatusCode!=status||strings.Contains(string(body),"private"){t.Fatal(response.StatusCode,string(body),err)};cancel();writer.Close()})}}}
func TestResponseMediaConflictFailsBeforeOpen(t *testing.T){source:=new(rejectionSource);var reported error;handler,err:=NewHandler("/",Definition{Method:"POST"},Options{OnError:func(_ context.Context,err error){reported=err}},func(*Execution,ParameterResult)(Response,error){return Response{Status:200,HasBody:true,Body:types.BinaryFromSource(source),Headers:http.Header{"Content-Type":{"application/json"}}},nil});if err!=nil{t.Fatal(err)};recorder:=httptest.NewRecorder();handler.ServeHTTP(recorder,httptest.NewRequest("POST","/",nil));var failure *Error;if recorder.Code!=500||source.opens.Load()!=0||!errors.As(reported,&failure)||failure.Code!=InboundResponseInvalid{t.Fatal(recorder.Code,source.opens.Load(),reported)}}

type blockedResponseSource struct{body *blockedBody;context context.Context;canceled atomic.Bool}
func(source *blockedResponseSource)Metadata()types.BinaryMetadata{return types.BinaryMetadata{ContentType:"text/plain"}}
func(source *blockedResponseSource)Open(ctx context.Context)(io.ReadCloser,error){source.context=ctx;return &blockedResponseReader{source:source},nil}
type blockedResponseReader struct{source *blockedResponseSource}
func(reader *blockedResponseReader)Read(buffer []byte)(int,error){return reader.source.body.Read(buffer)}
func(reader *blockedResponseReader)Close()error{reader.source.canceled.Store(reader.source.context.Err()!=nil);return reader.source.body.Close()}
func TestDisconnectInterruptsBlockedResponseSource(t *testing.T){source:=&blockedResponseSource{body:&blockedBody{started:make(chan struct{}),closed:make(chan struct{})}};handler,err:=NewHandler("/",Definition{Method:"POST"},Options{},func(*Execution,ParameterResult)(Response,error){return Response{Status:200,HasBody:true,Streaming:true,Body:types.BinaryFromSource(source)},nil});if err!=nil{t.Fatal(err)};done:=make(chan struct{});server:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){defer close(done);handler.ServeHTTP(w,r)}));defer server.Close();defer source.body.close.Do(func(){close(source.body.closed)});ctx,cancel:=context.WithTimeout(context.Background(),5*time.Second);defer cancel();request,_:=http.NewRequestWithContext(ctx,"POST",server.URL,nil);response,err:=server.Client().Do(request);if err!=nil{t.Fatal(err)};defer response.Body.Close();select{case <-source.body.started:case <-time.After(2*time.Second):t.Fatal("response source read did not start")};cancel();response.Body.Close();select{case <-done:case <-time.After(2*time.Second):t.Fatal("disconnect left response read blocked")};if source.body.closes.Load()!=1||!source.canceled.Load(){t.Fatal("source canceled/closed ownership",source.body.closes.Load(),source.canceled.Load())}}

`
